    LineupSpot = apps.get_model("matchday", "LineupSpot")
    for match in Match.objects.all():
        keepers = {match.home_goalkeeper_id, match.away_goalkeeper_id}
        spots = LineupSpot.objects.filter(
            lineup_id=match.lineup_id, team_id__in=[match.home_team_id, match.away_team_id]
        )
        MatchPlayer.objects.bulk_create(
            MatchPlayer(match=match, player_id=spot.player_id, team_id=spot.team_id)
            for spot in spots
            if spot.player_id not in keepers
        )
        if match.finished_at is not None:
            Match.objects.filter(pk=match.pk).update(roster_follows_lineup=False)


